const fs = require('node:fs');
const path = require('node:path');
const profile = JSON.parse(fs.readFileSync(path.join(__dirname, 'baseline-1000-document.cpuprofile'), 'utf8'));
const nodes = new Map(profile.nodes.map(node => [node.id, node])), parents = new Map(), self = new Map(), inclusive = new Map();
for (const node of profile.nodes) for (const child of node.children || []) parents.set(child, node.id);
for (let i = 0; i < profile.samples.length; i++) {
    let id = profile.samples[i]; const ms = profile.timeDeltas[i] / 1000;
    self.set(id, (self.get(id) || 0) + ms);
    while (id !== undefined) {inclusive.set(id, (inclusive.get(id) || 0) + ms); id = parents.get(id);}
}
function top(values, count) {return [...values].sort((a, b) => b[1] - a[1]).slice(0, count).map(([id, ms]) => {
    const node = nodes.get(id), f = node.callFrame;
    return {id, ms: Math.round(ms), function: f.functionName || '(anonymous)', url: f.url.split('/').at(-1), line: f.lineNumber, column: f.columnNumber,
        parent: nodes.get(parents.get(id))?.callFrame.functionName};
});}
const result = {durationMs: (profile.endTime - profile.startTime) / 1000, samples: profile.samples.length, self: top(self, 35), inclusive: top(inclusive, 35)};
fs.writeFileSync(path.join(__dirname, 'cpu-summary.json'), JSON.stringify(result, null, 2));
console.log(JSON.stringify(result));

