// Diagnostic only. Explicit immutable artifact/source, not acceptance timings.
const fs = require('node:fs'), path = require('node:path'), {createHash} = require('node:crypto');
const {execFileSync} = require('node:child_process');
const root = path.resolve(__dirname, '../../..');
const [label, artifact, sourceRevision, mode = 'canvas', countText = '1000'] = process.argv.slice(2);
if (!/^[a-z0-9-]+$/.test(label || '') || !artifact || !/^[0-9a-f]{40}$/.test(sourceRevision || '')) throw Error('Supply label, immutable artifact path, full source SHA, mode and count');
execFileSync('git', ['cat-file', '-e', sourceRevision + '^{commit}'], {cwd: root});
const extensionPath = path.resolve(artifact), profilePath = path.join(__dirname, label + '.cpuprofile');
if (fs.existsSync(profilePath)) throw Error('Refusing to overwrite a diagnostic');
const hash = createHash('sha256');
function walk(directory) {
    for (const entry of fs.readdirSync(directory, {withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name))) {
        const file=path.join(directory,entry.name);
        if(entry.isDirectory()) walk(file); else {hash.update(path.relative(extensionPath,file).replaceAll('\\','/'));hash.update(fs.readFileSync(file));}
    }
}
walk(extensionPath); const artifactDigest=hash.digest('hex');
let source=fs.readFileSync(path.join(root,'tests/helpers/nativeProbeWorker.js'),'utf8');
source=source.replace("require('./nativeBoardFixture')",'require('+JSON.stringify(path.join(root,'tests/helpers/nativeBoardFixture.js'))+')')
    .replace("require('./largeLibraryFixture')",'require('+JSON.stringify(path.join(root,'tests/helpers/largeLibraryFixture.js'))+')');
source=source.replace('let ok = false;',`let ok = false, profileSession;
    const saveProfile = async () => {
        if (!profileSession) return;
        const session = profileSession; profileSession = undefined;
        const {profile} = await session.send('Profiler.stop');
        require('node:fs').writeFileSync(${JSON.stringify(profilePath)}, JSON.stringify(profile));
        await session.detach();
    };`);
source=source.replace("await measure('workspaceReady', async () => {",`profileSession=await context.newCDPSession(page);
        await profileSession.send('Profiler.enable');
        await profileSession.send('Profiler.setSamplingInterval',{interval:1000});
        await profileSession.send('Profiler.start');
        await measure('workspaceReady', async () => {`);
source=source.replace('const editable = ws.locator(',`await saveProfile();
        metrics.lookupFallback=await page.evaluate(()=>window.nativeLookupFallback);
        const editable = ws.locator(`);
source=source.replace("document.addEventListener('DOMContentLoaded', () => new MutationObserver",`const append=Element.prototype.append;
            Element.prototype.append=function(...nodes) {
                const editor=nodes.find(node=>['edgeless-editor','page-editor'].includes(node?.localName));
                if(editor?.doc) {
                    const doc=editor.doc;
                    doc.spaceDoc.on('beforeTransaction',()=> {
                        if(!Object.hasOwn(doc,'getParent')&&!window.nativeLookupFallback) window.nativeLookupFallback={stack:new Error('Lookup fallback').stack,status:document.querySelector('.affineWorkspace [role="status"]')?.textContent};
                    });
                }
                return append.apply(this,nodes);
            };
            document.addEventListener('DOMContentLoaded', () => new MutationObserver`);
source=source.replace("process.send({type: 'result', result: {ok, metrics, errors}});",`try {await saveProfile();} catch(error){ok=false;errors.push('CPU profile: '+error.message);}
    process.send({type:'result',result:{ok,metrics,errors}});`);
const workerPath=path.join(__dirname,label+'-worker.cjs');fs.writeFileSync(workerPath,source);
const {runOwnedNativeProbe}=require(path.join(root,'tests/helpers/nativeProbeRunner'));
runOwnedNativeProbe({extensionPath,referenceCount:Number(countText),mode,sample:0,timeoutMs:180000,label}, {workerPath}).then(result=>{
    fs.writeFileSync(path.join(__dirname,label+'.json'),JSON.stringify({scope:'Instrumented diagnostic, excluded from acceptance medians',sourceRevision,artifactDigest,mode,count:Number(countText),cpuProfile:path.basename(profilePath),...result},null,2)+'\n');
    console.log(JSON.stringify({ok:result.ok,ready:result.metrics.workspaceReady,lookupFallback:result.metrics.lookupFallback,revealFailure:result.metrics.revealFailure,errors:result.errors.map(e=>e.slice(0,300))}));
    if(!result.ok)process.exitCode=1;
}).catch(error=>{console.error(error);process.exitCode=1;});

