 fs.writeFileSync(path.join(__dirname,'content-trace.json'),JSON.stringify({scope:'Instrumented derived-artifact diagnostic; excluded from acceptance',sourceRevision:'977e57f987f5b4be63bdf820c7581b1a02bc3d6d',...result},null,2)+'\n');
 console.log(JSON.stringify({ok:result.ok,ready:result.metrics.workspaceReady,failure:result.metrics.revealFailure}));if(!result.ok)process.exitCode=1;
